<!doctype html>
<html lang="ru">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{{ $title ?? 'ZharZhar' }}</title><style>body{margin:0;background:#f7f5ef;color:#17332a;font-family:Arial,sans-serif}.shell{max-width:1180px;margin:0 auto;padding:32px 24px}header,.card-head,.section-head{display:flex;justify-content:space-between;align-items:center;gap:18px}header{border-bottom:1px solid #ddd8cc;padding-bottom:20px}.brand{font-size:24px;font-weight:700;margin-top:8px}.button{display:inline-flex;align-items:center;justify-content:center;background:#c4634b;color:white;border:0;padding:12px 18px;cursor:pointer;text-decoration:none;font-weight:700}.button.secondary{background:#17332a}.button.whatsapp{background:#16834f}.button.full{width:100%;box-sizing:border-box}.actions,.row-actions{display:flex;gap:10px;align-items:center}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:18px}.admin-columns{display:grid;grid-template-columns:minmax(280px,.85fr) minmax(380px,1.15fr);gap:18px}.card{background:#fffdf8;border:1px solid #ddd8cc;padding:22px}.restaurant-card{margin-bottom:12px}.muted,small{color:#6e776f}.error{color:#a33;margin:8px 0}.success{color:#26724d;background:#e5efe8;padding:12px}.form-stack{display:grid;gap:13px}.form-stack label{font-size:14px}.form-stack input,.form-stack select,.form-stack textarea{display:block;width:100%;padding:11px;margin-top:6px;box-sizing:border-box;border:1px solid #ccc6b9;background:#fff}.form-stack small{display:block;margin-top:5px}.check{display:flex!important;align-items:center;gap:8px}.check input{display:inline-block;width:auto;margin:0}.edit-restaurant-form{padding-top:15px}.text-link,.booking-name,.row-actions a{color:#17332a;font-weight:700;text-decoration:underline}.whatsapp-link{color:#16834f;font-weight:700}.status{display:inline-block;padding:5px 9px;border-radius:4px;background:#eee7d7;font-size:12px;font-weight:700;white-space:nowrap}.status-confirmed,.status-active{background:#dcebdd;color:#225e3f}.status-cancelled,.status-inactive{background:#f1deda;color:#88362e}.table-scroll{overflow-x:auto}table{width:100%;border-collapse:collapse;background:#fffdf8}th,td{text-align:left;padding:12px;border-bottom:1px solid #ddd8cc;vertical-align:top}th{font-size:12px}.section-head{margin-top:28px}.section-head h2{margin-bottom:4px}.booking-detail-grid{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(260px,.7fr);gap:20px;margin-top:24px}.booking-main-card h1{margin-top:0}.eyebrow{font-size:11px;letter-spacing:1.5px;font-weight:700}.detail-list{margin:25px 0 0}.detail-list div{display:grid;grid-template-columns:190px 1fr;gap:15px;padding:12px 0;border-bottom:1px solid #e2ded3}.detail-list dt{color:#6e776f}.detail-list dd{margin:0}details{border-top:1px solid #ddd8cc;margin-top:16px;padding-top:12px}summary{cursor:pointer;font-weight:700}@media(max-width:760px){.admin-columns,.booking-detail-grid{grid-template-columns:1fr}.shell{padding:20px 14px}header,.card-head{align-items:flex-start;flex-direction:column}.actions{flex-wrap:wrap}.detail-list div{grid-template-columns:1fr;gap:3px}th,td{padding:10px}}</style></head>
